js.text:

function grid$khxlApprove(f){
  this.constructor(f);
}
grid$khxlApprove.prototype = new DirEvent();
grid$khxlApprove.prototype.afterInit = function(renderType){
  var p = this._dir;
  if (p.options._status == 1) p.find(".toolbar-approve").attr('title', p.msg('approve'))
  else if (p.options._status == 5) p.find(".toolbar-approve").attr('title', p.msg('undo'))
  else p.find(".toolbar-approve").attr('title', p.msg('open'));
  p.find(".toolbar-cancel").css("display", (p.options._status == 1)?"":"none")
}
grid$khxlApprove.prototype.beforeButtonGridClick = function (id, gindex) {

  var msg, p = this._dir, g = p.grid(gindex), dt = g.data, fees = p.selectedItems(), xstatus = p.options._status;
  switch (id) {

    case 'approve':
      msg = (xstatus ==1)? p.msg('msg1'): (xstatus == 9)? p.msg('msg3'):p.msg('msg2');
      if (fees.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('Approve', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;
    case 'cancel':
      if (fees.count() > 0)
        p.showFilter('messageInput', null, {title: p.msg('inputTitle'), label: p.msg('reason'), allowBlank: false, msgFunction: function (q, v, ctext) {
          q._close();
          if (v){
            p.request('Close', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus], ['ly_do_huy', 'C', ctext]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        }});
      return false;
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}

dir.script:



declare @deststatus int, @uid int, @dduyet date, @DetailTable varchar(32), @MasterTable varchar(32), @key nvarchar(4000) = '',  @s NVARCHAR(4000)
set @deststatus = case @xstatus when 1 then 5 when 5 then 1 else 5 end --else 9 - Huy thi tra ve duyet
set @uid = case when @xstatus = 1 then @@userId else 0 end
set @dduyet = case when @xstatus = 1 then getdate() else null end

update dmkh0 set status = @deststatus, user_id_duyet = @uid, ngay_duyet = @dduyet where ma_so_thue in (select ma_so_thue from @tblKeys);

SELECT @key = STRING_AGG(ma_so_thue, ',') FROM @tblKeys;

exec dbo.InsertDMKH 'dmkh0', '', @key, @deststatus;

select '' as message, '$Processed' as toast




    &VoucherJSLoading;
